55	// Sync DB and Start Server
56	const db = require('./models');
57	const startCleanupCron = require('./cron/cleanupTranscripts');
58	// Cloud-compatible binding: PORT (cloud) -> APP_PORT (local .env) -> 5001,
59	// listening on 0.0.0.0 so deployed containers accept external traffic.
60	const { resolvePort, resolveHost } = require('./config/serverConfig');
61	
62	async function startServer() {
63	    try {
64	        // IMPORTANT: faceVector is stored as a PostgreSQL FLOAT[] (Sequelize ARRAY(FLOAT)),
65	        // NOT pgvector. We intentionally do NOT create the pgvector extension or drop the
66	        // "faceVector" column on startup. The previous drop-on-fallback logic wiped every
67	        // enrolled face on each restart, so it has been removed. Sequelize sync (below)
68	        // manages the column safely without data loss.
69	
70	        const modelNames = Object.keys(db).filter(
71	            k => k !== 'sequelize' && k !== 'Sequelize'
72	        );
73	        const failedModels = [];
74	
75	        // Schema alteration is opt-in: set DB_SYNC_ALTER=true only when a model
76	        // schema intentionally changed. Normal startup creates missing tables
77	        // but never re-alters every existing table (and never uses force).
78	        const alterSchema = process.env.DB_SYNC_ALTER === 'true';
79	
80	        // Visible startup progress: the HTTP listener only binds AFTER this
81	        // loop, so a slow remote database must never look like a silent hang
82	        // (the classic symptom is the Vite proxy timing out on 127.0.0.1:5001).
83	        console.log(`Syncing ${modelNames.length} models (alter:${alterSchema}) - port ${resolvePort()} opens when this finishes...`);
84	        const syncStart = Date.now();
85	
86	        for (const [i, name] of modelNames.entries()) {
87	            // Heartbeat: if one model sync stalls (slow/unreachable DB), keep
88	            // saying so instead of going quiet.
89	            const heartbeat = setInterval(() => {
90	                console.log(`  ... still syncing ${name} (${Math.round((Date.now() - syncStart) / 1000)}s elapsed) - check DB_HOST/network if this persists`);
91	            }, 10000);
92	            const modelStart = Date.now();
93	            try {
94	                await db[name].sync({ alter: alterSchema });
95	                console.log(`  OK [${i + 1}/${modelNames.length}] Synced: ${name} (${Date.now() - modelStart}ms)`);
96	            } catch (syncErr) {
97	                failedModels.push(name);
98	                console.error(`  FAIL [${i + 1}/${modelNames.length}] Failed to sync ${name}:`, syncErr.message);
99	            } finally {
100	                clearInterval(heartbeat);
101	            }
102	        }
103	        console.log(`Model sync finished in ${Math.round((Date.now() - syncStart) / 1000)}s.`);
104	
105	        if (failedModels.length > 0) {
106	            console.warn(`\nWARNING: ${failedModels.length} model(s) failed to sync: ${failedModels.join(', ')}`);
107	            console.warn("The server will start, but those tables may be missing or outdated.\n");
108	        }
109	
110	        // Start PDPA 90-day transcript cleanup cron
111	        startCleanupCron(db);
112	
113	        const port = resolvePort();
114	        const host = resolveHost();
115	        app.listen(port, host, () => {
116	            console.log("--------------------------------------------------");
117	            console.log(`FlowGuard Server is FULLY READY on ${host}:${port}`);
118	            console.log("--------------------------------------------------");
119	        });
120	    } catch (err) {
121	        console.error("Database Sync Error: ", err);
122	    }
123	}
124	
125	startServer();
