1	const express = require('express');
2	const router = express.Router();
3	const crypto = require('crypto');
4	const { Op } = require('sequelize');
5	const { Booking, User } = require('../models');
6	const { verifyToken, requireRole } = require('../middlewares/auth');
7	const whatsapp = require('../services/whatsappService');
8	const { verifyGate } = require('../services/gateVerification');
9	const { normalizeSlots, parseBookingDateTime } = require('../utils/bookingDateTime');
10	
11	const STATUSES = ['Pending', 'Confirmed', 'Arrived', 'Completed', 'Cancelled'];
12	
13	function genRef() {
14	    return `FG-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
15	}
16	
17	// Resolve which tenant/unit a booking belongs to, based on who is creating it:
18	//   Tenant → their own id; Staff → their managerId (the tenant they work for); FM → optional body.tenantId.
19	// Returns null if it cannot be determined (FM with no tenantId, or Staff with no manager).
20	async function resolveTenantId(user, bodyTenantId) {
21	    if (user.role === 'Tenant') return user.id;
22	    if (user.role === 'Staff') {
23	        const staff = await User.findByPk(user.id, { attributes: ['managerId'] });
24	        return staff?.managerId ?? null;
25	    }
26	    return bodyTenantId || null; // FM
27	}
28	
29	// ---------------------------------------------------------------------------
30	// CREATE — FM, Tenant, or Staff create a loading-bay booking request. (400 on bad input)
31	// Staff may book on behalf of their tenant/unit (booking is linked to their managerId).
32	// ---------------------------------------------------------------------------
33	router.post('/create', verifyToken, requireRole('FM', 'Tenant', 'Staff'), async (req, res) => {
34	    try {
35	        const {
36	            transport_company, license_plate, driver_phone, loading_bay,
37	            driver_name, slot_start, slot_end, notes, tenant_name
38	        } = req.body;
39	
40	        const missing = ['transport_company', 'license_plate', 'driver_phone', 'loading_bay']
41	            .filter(f => !req.body[f] || !String(req.body[f]).trim());
42	        if (missing.length) {
43	            return res.status(400).json({ error: `Missing required field(s): ${missing.join(', ')}.` });
44	        }
45	        if (!/^[+\d][\d\s-]{6,}$/.test(String(driver_phone))) {
46	            return res.status(400).json({ error: 'driver_phone is not a valid phone number.' });
47	        }
48	
49	        // Normalise slot times to absolute UTC instants BEFORE any validation,
50	        // conflict check or persistence. A timezone-less datetime-local value
51	        // (e.g. "2026-07-27T18:01") is interpreted as Singapore wall-clock time,
52	        // never re-parsed with the host machine's timezone (Cloud Run = UTC).
53	        const slots = normalizeSlots({ slot_start, slot_end });
54	        if (slots.error) return res.status(400).json({ error: slots.error });
55	        const startAt = slots.slot_start;
56	        const endAt = slots.slot_end;
57	
58	        // Optional slot-conflict guard (409) when a time window is supplied.
59	        if (startAt && endAt) {
60	            if (endAt <= startAt) {
61	                return res.status(400).json({ error: 'slot_end must be after slot_start.' });
62	            }
63	            const clash = await Booking.findOne({
64	                where: {
65	                    loading_bay,
66	                    status: { [Op.ne]: 'Cancelled' },
67	                    slot_start: { [Op.lt]: endAt },
68	                    slot_end: { [Op.gt]: startAt }
69	                }
70	            });
71	            if (clash) {
72	                return res.status(409).json({ error: `${loading_bay} is already booked for that time window.` });
73	            }
74	        }
75	
76	        // Link the booking to a tenant/unit so the right people can see it
77	        // (Tenant → self, Staff → their managerId, FM → optional body.tenantId).
78	        const tenantId = await resolveTenantId(req.user, req.body.tenantId);
79	
80	        const booking = await Booking.create({
81	            booking_ref: genRef(),
82	            transport_company,
83	            license_plate,
84	            driver_phone,
85	            loading_bay,
86	            driver_name: driver_name || null,
87	            slot_start: startAt,
88	            slot_end: endAt,
89	            notes: notes || null,
90	            tenant_name: tenant_name || null,
91	            tenantId,
92	            status: 'Pending'
93	        });
94	
95	        // Confirmation to the driver — non-fatal (must never fail the booking).
96	        let whatsappResult = null;
97	        try {
98	            whatsappResult = await whatsapp.sendBookingCreated(booking);
99	        } catch (waErr) {
100	            console.error('WhatsApp notify failed (non-fatal):', waErr.message);
101	        }
102	
103	        res.status(201).json({ message: 'Booking created.', booking, whatsapp: whatsappResult });
104	    } catch (err) {
105	        console.error('Booking create error:', err);
106	        res.status(500).json({ error: 'Internal server error while creating booking.' });
107	    }
108	});
109	
110	// ---------------------------------------------------------------------------
111	// READ (list) — FM sees all; Tenant sees own unit; Staff sees their unit's bookings.
112	// ---------------------------------------------------------------------------
113	router.get('/', verifyToken, async (req, res) => {
114	    try {
115	        const where = {};
116	        if (req.user.role === 'Tenant') {
117	            where.tenantId = req.user.id;
118	        } else if (req.user.role === 'Staff') {
119	            // Staff only see bookings for the tenant/unit they belong to.
120	            const tenantId = await resolveTenantId(req.user, null);
121	            where.tenantId = tenantId ?? -1; // -1 → matches nothing if no manager set
122	        }
123	        // FM → no filter (all bookings)
124	        const bookings = await Booking.findAll({ where, order: [['createdAt', 'DESC']], limit: 100 });
125	        res.status(200).json(bookings);
126	    } catch (err) {
127	        console.error('Booking list error:', err);
128	        res.status(500).json({ error: 'Could not retrieve bookings.' });
129	    }
130	});
131	
132	// READ (all) — FM-only compat alias (unscoped). Declared BEFORE '/:ref'.
133	router.get('/all', verifyToken, requireRole('FM'), async (req, res) => {
134	    try {
135	        const bookings = await Booking.findAll({ order: [['createdAt', 'DESC']], limit: 100 });
136	        res.status(200).json(bookings);
137	    } catch (err) {
138	        console.error('Booking list error:', err);
139	        res.status(500).json({ error: 'Could not retrieve bookings.' });
140	    }
141	});
142	
143	// ---------------------------------------------------------------------------
144	// UPDATE status — FM only (facility-level: Pending → Confirmed → Arrived → Completed).
145	// Confirmed → WhatsApp slot confirmation. Completed → auto next-in-line alert.
146	// ---------------------------------------------------------------------------
147	router.patch('/:id/status', verifyToken, requireRole('FM'), async (req, res) => {
148	    try {
149	        const { status } = req.body;
150	        if (!STATUSES.includes(status)) {
151	            return res.status(400).json({ error: `status must be one of: ${STATUSES.join(', ')}.` });
152	        }
153	
154	        const booking = await Booking.findByPk(req.params.id);
155	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
156	
157	        await booking.update({ status });
158	
159	        let whatsappResult = null;
160	        let nextInLine = null;
161	
162	        // All WhatsApp sends are non-fatal — a failure must never fail the status update.
163	        try {
164	            if (status === 'Confirmed') {
165	                whatsappResult = await whatsapp.sendBookingConfirmed(booking);
166	            } else if (status === 'Arrived') {
167	                whatsappResult = await whatsapp.sendBookingArrived(booking);
168	            } else if (status === 'Cancelled') {
169	                whatsappResult = await whatsapp.sendBookingCancelled(booking);
170	            } else if (status === 'Completed') {
171	                // Notify the leaving driver, then alert the next waiting booking for the same bay.
172	                whatsappResult = await whatsapp.sendBookingCompleted(booking);
173	                const next = await Booking.findOne({
174	                    where: { loading_bay: booking.loading_bay, status: { [Op.in]: ['Pending', 'Confirmed'] } },
175	                    order: [['slot_start', 'ASC'], ['createdAt', 'ASC']]
176	                });
177	                if (next) {
178	                    await whatsapp.sendNextInLine(next);
179	                    nextInLine = next.booking_ref;
180	                }
181	            }
182	        } catch (waErr) {
183	            console.error('WhatsApp notify failed (non-fatal):', waErr.message);
184	        }
185	
186	        res.status(200).json({ message: `Booking ${status}.`, booking, whatsapp: whatsappResult, nextInLine });
187	    } catch (err) {
188	        console.error('Booking status error:', err);
189	        res.status(500).json({ error: 'Could not update booking status.' });
190	    }
191	});
192	
193	// ---------------------------------------------------------------------------
194	// EDIT — manual booking update. FM may edit any booking; a Tenant may edit
195	// only their own unit's bookings. Closed bookings cannot be edited.
196	// Editable fields only — status changes stay on /:id/status and /:ref/gate-scan,
197	// and cancellation remains the soft-delete on /:id/cancel.
198	// ---------------------------------------------------------------------------
199	const EDITABLE_FIELDS = [
200	    'transport_company', 'driver_name', 'driver_phone', 'license_plate',
201	    'loading_bay', 'slot_start', 'slot_end', 'notes'
202	];
203	
204	router.patch('/:id', verifyToken, requireRole('FM', 'Tenant'), async (req, res) => {
205	    try {
206	        const booking = await Booking.findByPk(req.params.id);
207	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
208	
209	        const isFM = req.user.role === 'FM';
210	        const isOwnerTenant = req.user.role === 'Tenant' && booking.tenantId === req.user.id;
211	        if (!isFM && !isOwnerTenant) {
212	            return res.status(403).json({ error: 'You can only edit your own bookings.' });
213	        }
214	        if (['Completed', 'Cancelled'].includes(booking.status)) {
215	            return res.status(409).json({ error: `Cannot edit a ${booking.status} booking.` });
216	        }
217	
218	        // Whitelist — ignore any other fields (status, tenantId, booking_ref…).
219	        const updates = {};
220	        for (const field of EDITABLE_FIELDS) {
221	            if (field in req.body) updates[field] = req.body[field];
222	        }
223	        if (Object.keys(updates).length === 0) {
224	            return res.status(400).json({ error: 'No editable fields supplied.' });
225	        }
226	
227	        if ('driver_phone' in updates && !/^[+\d][\d\s-]{6,}$/.test(String(updates.driver_phone))) {
228	            return res.status(400).json({ error: 'driver_phone is not a valid phone number.' });
229	        }
230	
231	        // Normalise any edited slot times to absolute UTC instants (same
232	        // Singapore wall-clock contract as create) before validation/persistence.
233	        if ('slot_start' in updates) {
234	            const parsed = parseBookingDateTime(updates.slot_start);
235	            if (!parsed.ok) return res.status(400).json({ error: 'slot_start is not a valid date/time.' });
236	            updates.slot_start = parsed.date;
237	        }
238	        if ('slot_end' in updates) {
239	            const parsed = parseBookingDateTime(updates.slot_end);
240	            if (!parsed.ok) return res.status(400).json({ error: 'slot_end is not a valid date/time.' });
241	            updates.slot_end = parsed.date;
242	        }
243	
244	        // Slot-conflict validation on the resulting time window/bay. Existing
245	        // values from the DB are already absolute instants; coerce both sides to
246	        // Date so the comparison never depends on string parsing.
247	        const newStart = 'slot_start' in updates ? updates.slot_start : booking.slot_start;
248	        const newEnd = 'slot_end' in updates ? updates.slot_end : booking.slot_end;
249	        const newBay = 'loading_bay' in updates ? updates.loading_bay : booking.loading_bay;
250	        if (newStart && newEnd) {
251	            const startAt = newStart instanceof Date ? newStart : new Date(newStart);
252	            const endAt = newEnd instanceof Date ? newEnd : new Date(newEnd);
253	            if (endAt <= startAt) {
254	                return res.status(400).json({ error: 'slot_end must be after slot_start.' });
255	            }
256	            const clash = await Booking.findOne({
257	                where: {
258	                    id: { [Op.ne]: booking.id }, // ignore the booking being edited
259	                    loading_bay: newBay,
260	                    status: { [Op.ne]: 'Cancelled' },
261	                    slot_start: { [Op.lt]: endAt },
262	                    slot_end: { [Op.gt]: startAt }
263	                }
264	            });
265	            if (clash) {
266	                return res.status(409).json({ error: `${newBay} is already booked for that time window.` });
267	            }
268	        }
269	
270	        await booking.update(updates);
271	        res.status(200).json({ message: 'Booking updated.', booking });
272	    } catch (err) {
273	        console.error('Booking edit error:', err);
274	        res.status(500).json({ error: 'Could not update booking.' });
275	    }
276	});
277	
278	// ---------------------------------------------------------------------------
279	// CANCEL — FM, or the Tenant who owns it. Soft cancel (status='Cancelled').
280	// ---------------------------------------------------------------------------
281	router.patch('/:id/cancel', verifyToken, async (req, res) => {
282	    try {
283	        const booking = await Booking.findByPk(req.params.id);
284	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
285	
286	        const isFM = req.user.role === 'FM';
287	        const isOwnerTenant = req.user.role === 'Tenant' && booking.tenantId === req.user.id;
288	        if (!isFM && !isOwnerTenant) {
289	            return res.status(403).json({ error: 'You can only cancel your own bookings.' });
290	        }
291	
292	        await booking.update({ status: 'Cancelled' });
293	
294	        // WhatsApp is non-fatal — a notify failure must never fail the cancel.
295	        let whatsappResult = null;
296	        try {
297	            whatsappResult = await whatsapp.sendBookingCancelled(booking);
298	        } catch (waErr) {
299	            console.error('WhatsApp notify failed (non-fatal):', waErr.message);
300	        }
301	
302	        res.status(200).json({ message: 'Booking cancelled.', booking, whatsapp: whatsappResult });
303	    } catch (err) {
304	        console.error('Booking cancel error:', err);
305	        res.status(500).json({ error: 'Could not cancel booking.' });
306	    }
307	});
308	
309	// ---------------------------------------------------------------------------
310	// GATE SCAN — FM only: scan/verify a driver pass by booking_ref at the bay.
311	//   body: { action: 'entry' | 'exit', observedPlate?: string }
312	//   entry: Pending/Confirmed → Arrived (+ WhatsApp arrival)
313	//   exit:  Arrived/Confirmed → Completed (+ WhatsApp completed + next-in-line)
314	// Plate mismatch is flagged (warn) but does not block. WhatsApp is non-fatal.
315	// ---------------------------------------------------------------------------
316	router.patch('/:ref/gate-scan', verifyToken, requireRole('FM'), async (req, res) => {
317	    try {
318	        const { action, observedPlate } = req.body;
319	        if (!['entry', 'exit'].includes(action)) {
320	            return res.status(400).json({ error: "action must be 'entry' or 'exit'." });
321	        }
322	
323	        const booking = await Booking.findOne({ where: { booking_ref: req.params.ref } });
324	        if (!booking) return res.status(404).json({ error: 'Booking not found.' });
325	
326	        // Optional plate verification (warn-only — never blocks the scan).
327	        let plateMatched = null;
328	        if (observedPlate && String(observedPlate).trim()) {
329	            const norm = (s) => String(s || '').toUpperCase().replace(/\s+/g, '');
330	            plateMatched = norm(observedPlate) === norm(booking.license_plate);
331	        }
332	
333	        let whatsappStatus = null;
334	        let nextInLine = null;
335	
336	        if (action === 'entry') {
337	            if (booking.status === 'Cancelled' || booking.status === 'Completed') {
338	                return res.status(409).json({ error: `Cannot mark arrival: booking is ${booking.status}.`, booking, plateMatched });
339	            }
340	            await booking.update({ status: 'Arrived', arrived_at: new Date() });
341	            try {
342	                whatsappStatus = await whatsapp.sendBookingArrived(booking);
343	            } catch (waErr) {
344	                console.error('WhatsApp notify failed (non-fatal):', waErr.message);
345	            }
346	        } else { // exit
347	            if (booking.status === 'Cancelled') {
348	                return res.status(409).json({ error: 'Cannot mark exit: booking is Cancelled.', booking, plateMatched });
349	            }
350	            if (booking.status === 'Completed') {
351	                // Idempotent — already completed, do not re-notify / re-trigger next-in-line.
352	                return res.status(200).json({
353	                    message: 'Booking already completed.', booking, action,
354	                    plateMatched, whatsappStatus: null, nextInLine: null, alreadyCompleted: true
355	                });
356	            }
357	            await booking.update({ status: 'Completed', completed_at: new Date() });
358	            try {
359	                whatsappStatus = await whatsapp.sendBookingCompleted(booking);
360	                const next = await Booking.findOne({
361	                    where: { loading_bay: booking.loading_bay, status: { [Op.in]: ['Pending', 'Confirmed'] } },
362	                    order: [['slot_start', 'ASC'], ['createdAt', 'ASC']]
363	                });
364	                if (next) {
365	                    await whatsapp.sendNextInLine(next);
366	                    nextInLine = next.booking_ref;
367	                }
368	            } catch (waErr) {
369	                console.error('WhatsApp notify failed (non-fatal):', waErr.message);
370	            }
371	        }
372	
373	        return res.status(200).json({
374	            message: `Gate ${action} recorded.`, booking, action, plateMatched, whatsappStatus, nextInLine
375	        });
376	    } catch (err) {
377	        console.error('Gate scan error:', err);
378	        return res.status(500).json({ error: 'Could not process gate scan.' });
379	    }
380	});
381	
382	// ---------------------------------------------------------------------------
383	// GATE VERIFICATION — FM only: dual-mode (automatic QR+plate / manual) loading-bay
384	// gate decision. Delegates ALL rules + audit to the stateless gateVerification
385	// service (booking is re-read from PostgreSQL with a row lock on every call).
386	//   body: { action, bookingRef, observedPlate, verificationMode, plateSource,
387	//           plateConfidence, manualOverride, overrideReason }
388	// Returns a stable decision keyed by reasonCode (200 = decision made; 400 = bad
389	// request; 500 = server/audit failure — access NOT granted). This is additive:
