99	// Returns { code, warning? } for the entry arrival-window check.
100	function checkArrivalWindow(booking, now) {
101	  if (!booking.slot_start || !booking.slot_end) {
102	    return { code: null, warning: 'SCHEDULE_UNVERIFIED' }; // allowed, but flagged
103	  }
104	  const { earlyMin, lateMin } = graceWindow();
105	  const start = new Date(booking.slot_start).getTime();
106	  const end = new Date(booking.slot_end).getTime();
107	  if (Number.isNaN(start) || Number.isNaN(end)) {
108	    return { code: null, warning: 'SCHEDULE_UNVERIFIED' };
109	  }
110	  const nowMs = now.getTime();
111	  if (nowMs < start - earlyMin * 60000) return { code: REASON.TOO_EARLY };
112	  if (nowMs > end + lateMin * 60000) return { code: REASON.TOO_LATE };
113	  return { code: null };
114	}
