116	// Pure decision core. Given the loaded booking + normalised inputs, decide the
117	// base outcome WITHOUT touching the DB. Returns a plain decision descriptor.
118	function decide(booking, input, now) {
119	  const { action, verificationMode, observedPlate, plateSource } = input;
120	  const expectedPlate = normalizePlate(booking.license_plate);
121	  const observed = normalizePlate(observedPlate);
122	  const hasPlate = observed.length > 0;
123	  const plateMatched = hasPlate ? observed === expectedPlate : null;
124	
125	  const base = {
126	    expectedPlate,
127	    observedPlate: observed || null,
128	    plateMatched,
129	    warning: null,
130	  };
131	
132	  if (action === 'entry') {
133	    if (booking.status === 'Cancelled') return { ...base, grant: false, code: REASON.BOOKING_CANCELLED };
134	    if (booking.status === 'Completed') return { ...base, grant: false, code: REASON.BOOKING_COMPLETED };
135	    if (booking.status === 'Arrived') return { ...base, grant: true, code: REASON.ALREADY_ARRIVED, idempotent: true };
136	    if (booking.status !== 'Confirmed') return { ...base, grant: false, code: REASON.BOOKING_NOT_CONFIRMED };
137	
138	    // Confirmed → time window, then plate.
139	    const window = checkArrivalWindow(booking, now);
140	    if (window.code) return { ...base, grant: false, code: window.code };
141	    base.warning = window.warning || null;
142	
143	    const plate = evaluatePlate({ hasPlate, plateMatched, verificationMode, plateSource });
144	    if (plate) return { ...base, grant: false, code: plate };
145	    return { ...base, grant: true, code: REASON.VERIFIED, transitionTo: 'Arrived' };
146	  }
147	
148	  // action === 'exit'
149	  if (booking.status === 'Cancelled') return { ...base, grant: false, code: REASON.BOOKING_CANCELLED };
150	  if (booking.status === 'Completed') return { ...base, grant: true, code: REASON.ALREADY_COMPLETED, idempotent: true };
151	  if (booking.status !== 'Arrived') return { ...base, grant: false, code: REASON.NOT_ARRIVED };
152	
153	  const plate = evaluatePlate({ hasPlate, plateMatched, verificationMode, plateSource });
154	  if (plate) return { ...base, grant: false, code: plate };
155	  return { ...base, grant: true, code: REASON.VERIFIED, transitionTo: 'Completed' };
156	}
