163	    if (verificationMode === 'automatic' && plateSource === 'ocr') return REASON.OCR_UNREADABLE;
164	    if (verificationMode === 'automatic' && plateSource === 'simulation') return REASON.OCR_UNREADABLE;
165	    return REASON.PLATE_REQUIRED;
166	  }
167	  return plateMatched ? null : REASON.PLATE_MISMATCH;
168	}
