177	    action: outcome.action,
178	    verificationMode: outcome.verificationMode,
179	    booking: bookingSummary(booking),
180	    expectedPlate: outcome.expectedPlate ?? null,
181	    observedPlate: outcome.observedPlate ?? null,
182	    plateMatched: outcome.plateMatched ?? null,
183	    manualReviewRequired: denied && REVIEWABLE.has(outcome.code),
184	    overrideUsed: Boolean(outcome.overrideUsed),
