267	      }, t);
268	      return {
269	        http: 200,
270	        body: toDecisionBody(
271	          { grant: false, code: REASON.BOOKING_NOT_FOUND, action, verificationMode, expectedPlate: null, observedPlate: null, plateMatched: null },
