305	      action,
306	      verificationMode,
307	      plateSource,
308	      plateConfidence,
309	      expectedPlate: outcome.expectedPlate ?? null,
310	      observedPlate: outcome.observedPlate ?? null,
311	      plateMatched: outcome.plateMatched ?? null,
312	      loadingBay: booking.loading_bay,
313	      overrideUsed: Boolean(outcome.overrideUsed),
