1	// Minimal in-memory fixed-window rate limiter for the PoC (single Node
2	// process). Keyed per client IP by default; used to throttle the public
3	// forgot-password endpoint so it can't be used to spam mail or probe accounts.
4	const createRateLimiter = ({ windowMs = 15 * 60 * 1000, max = 5, keyFn } = {}) => {
5	    const hits = new Map(); // key -> { count, windowStart }
6	
7	    return (req, res, next) => {
8	        const now = Date.now();
9	        const key = keyFn ? keyFn(req) : (req.ip || req.socket?.remoteAddress || 'unknown');
10	
11	        const entry = hits.get(key);
12	        if (!entry || now - entry.windowStart >= windowMs) {
13	            hits.set(key, { count: 1, windowStart: now });
14	            return next();
15	        }
16	
17	        entry.count += 1;
18	        if (entry.count > max) {
19	            return res.status(429).json({ message: "Too many requests. Please try again later." });
20	        }
21	        next();
22	    };
23	};
24	
25	module.exports = { createRateLimiter };
