6	// (the Node service account needs roles/run.invoker on the AI service) BEFORE
7	// the request reaches FastAPI. The application-level X-AI-Service-Key header
8	// is kept as defence in depth — FastAPI still validates it itself.
9	//
10	// The ID token comes from the GCE/Cloud Run METADATA SERVER using the
11	// service's ATTACHED service account — no service-account JSON key file is
12	// ever present in the repo, image, or environment.
13	//
14	// Local development: the metadata server only exists on Google infrastructure.
15	// We only attempt to fetch a token when running on Cloud Run (K_SERVICE is set
16	// by the platform) or when AI_ID_TOKEN=force is set for testing. Everywhere
17	// else the headers contain only X-AI-Service-Key, so `npm run dev` needs no
18	// Google credentials at all.
19	
20	const axios = require('axios');
21	
22	const METADATA_IDENTITY_URL =
23	  'http://metadata.google.internal/computeMetadata/v1/instance/service-accounts/default/identity';
24	
25	// audience -> { token, expiresAtMs }
26	const tokenCache = new Map();
27	// Refresh 60s before expiry so a token never dies mid-request.
28	const EXPIRY_SKEW_MS = 60 * 1000;
29	
30	const shouldUseIdToken = (env = process.env) => {
31	  if (env.AI_ID_TOKEN === 'off') return false;   // explicit opt-out
32	  if (env.AI_ID_TOKEN === 'force') return true;  // testing override
33	  return Boolean(env.K_SERVICE);                 // set by Cloud Run itself
34	};
35	
36	// The Cloud Run audience is the receiving service's URL origin (never a path).
37	const audienceFor = (targetUrl) => new URL(targetUrl).origin;
38	
39	const decodeExpiryMs = (idToken) => {
40	  try {
41	    const payload = JSON.parse(Buffer.from(idToken.split('.')[1], 'base64url').toString('utf8'));
42	    return typeof payload.exp === 'number' ? payload.exp * 1000 : 0;
43	  } catch {
44	    return 0;
45	  }
46	};
47	
48	async function fetchIdToken(audience) {
49	  const cached = tokenCache.get(audience);
50	  if (cached && Date.now() < cached.expiresAtMs - EXPIRY_SKEW_MS) {
51	    return cached.token;
52	  }
53	  const response = await axios.get(METADATA_IDENTITY_URL, {
54	    params: { audience },
55	    headers: { 'Metadata-Flavor': 'Google' },
56	    timeout: 3000,
57	    responseType: 'text',
58	    // axios would otherwise JSON-parse; the body is the raw JWT string.
59	    transformResponse: [(data) => data]
60	  });
61	  const token = String(response.data || '').trim();
62	  if (!token) throw new Error('Metadata server returned an empty identity token.');
63	  tokenCache.set(audience, { token, expiresAtMs: decodeExpiryMs(token) });
64	  return token;
65	}
66	
67	/**
68	 * Headers for a Node -> AI-service request.
69	 * Always includes X-AI-Service-Key (app-level shared secret, defence in depth).
70	 * On Cloud Run also includes `Authorization: Bearer <Google ID token>` for the
71	 * private-service IAM check. A metadata-server failure is surfaced as a thrown
72	 * error ONLY on Cloud Run (where a missing token means a guaranteed 401/403);
73	 * locally no token is ever attempted.
74	 */
75	async function aiServiceHeaders(targetUrl, env = process.env) {
76	  const headers = { 'X-AI-Service-Key': env.AI_SERVICE_KEY || '' };
77	  if (!shouldUseIdToken(env)) return headers;
78	  const token = await fetchIdToken(audienceFor(targetUrl));
79	  headers['Authorization'] = `Bearer ${token}`;
80	  return headers;
81	}
82	
83	// Test hook — never used by production code paths.
84	const _clearTokenCache = () => tokenCache.clear();
85	
86	module.exports = { aiServiceHeaders, shouldUseIdToken, audienceFor, _clearTokenCache };
