22	const respondAiError = (res, err, serviceLabel) => {
23	  const isConnError = !err.response &&
24	    ['ECONNREFUSED', 'ECONNABORTED', 'ETIMEDOUT', 'ENOTFOUND'].includes(err.code);
25	  if (isConnError) {
26	    return res.status(503).json({ error: `${serviceLabel} is offline. Please try again shortly.` });
27	  }
28	  if (err.response) {
29	    const status = err.response.status === 400 ? 400 : 502;
30	    return res.status(status).json({ error: `${serviceLabel} returned an error.` });
31	  }
32	  console.error(`${serviceLabel} proxy error:`, err.message);
33	  return res.status(502).json({ error: `${serviceLabel} returned an error.` });
